package com.chubb.apac.claims.modulith.claim.service.impl;
import com.chubb.apac.claims.modulith.claim.event.ClaimCreatedEvent;import com.chubb.apac.claims.modulith.claim.model.*;import com.chubb.apac.claims.modulith.claim.repository.*;import com.chubb.apac.claims.modulith.claim.service.*;import com.chubb.apac.claims.modulith.common.enums.ClaimStatus;import com.chubb.apac.claims.modulith.incident.event.IncidentReportedEvent;import java.time.Instant;import java.util.UUID;import org.springframework.context.ApplicationEventPublisher;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class ClaimCreationServiceImpl implements ClaimCreationService {
 private final ClaimRepository claims;private final ClaimStatusHistoryRepository history;private final ClaimIdGenerator ids;private final IncidentProductResolver products;private final ApplicationEventPublisher events;
 public ClaimCreationServiceImpl(ClaimRepository claims,ClaimStatusHistoryRepository history,ClaimIdGenerator ids,IncidentProductResolver products,ApplicationEventPublisher events){this.claims=claims;this.history=history;this.ids=ids;this.products=products;this.events=events;}
 public void createFromIncident(IncidentReportedEvent e){if(claims.existsByIncidentId(e.incidentId()))return;Claim c=new Claim();c.setClaimId(ids.nextClaimId());c.setIncidentId(e.incidentId());c.setClaimantId(e.claimantId());c.setStatus(ClaimStatus.REPORTED);c.setProductType(products.resolve(e.incidentType()));c.setMarket(e.market());c.setCreatedBy(e.claimantId());c.setUpdatedBy(e.claimantId());claims.saveAndFlush(c);ClaimStatusHistory h=new ClaimStatusHistory();h.setClaimId(c.getClaimId());h.setOldStatus(null);h.setNewStatus(ClaimStatus.REPORTED);h.setReason("Claim created from reported incident");h.setChangedBy("system");h.setChangedAt(Instant.now());h.setCreatedBy("system");h.setUpdatedBy("system");history.save(h);events.publishEvent(new ClaimCreatedEvent(UUID.randomUUID().toString(),c.getClaimId(),c.getIncidentId(),c.getClaimantId(),c.getProductType(),c.getMarket(),Instant.now(),e.correlationId()));}
}
